INSERT INTO [auditlog_logentry]([rowid], [id], [object_pk], [object_id], [object_repr], [action], [timestamp], [actor_id], [content_type_id], [remote_addr], [additional_data], [serialized_data], [cid], [changes_text], [changes], [remote_port], [actor_email]) VALUES(6861, 6861, '1', 1, 'فروشگاه مرکزی', 1, '2025-07-06 08:31:36.057', 37, 23, '127.0.0.1', null, null, null, '', '{"is_verified": ["True", "False"], "description": ["<h2 style=\"text-align:right\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631\u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f DH-IPC-HFW3541TP-ZS</h2>\r\n\r\n<p style=\"text-align:right\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631 \u0628\u0633\u062a\u0647&nbsp;<u><a href=\"https://www.hik-look.com/dahua/\" target=\"_self\" title=\"\u062f\u0627\u0647\u0648\u0627\">\u062f\u0627\u0647\u0648\u0627</a></u>&nbsp;\u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0627\u0632 \u067e\u0631\u0641\u0631\u0648\u0634 \u062a\u0631\u06cc\u0646 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0633\u0631\u06cc \u062a\u062d\u062a \u0634\u0628\u06a9\u0647 \u06a9\u0645\u067e\u0627\u0646\u06cc \u062f\u0627\u0647\u0648\u0627 \u0645\u06cc\u0628\u0627\u0634\u062f \u06a9\u0647 \u0627\u0632 \u06a9\u06cc\u0641\u06cc\u062a \u0648 \u0642\u06cc\u0645\u062a \u0645\u0646\u0627\u0633\u0628\u06cc \u0628\u0631\u062e\u0648\u0631\u062f\u0627\u0631 \u0627\u0633\u062a.</p>\r\n\r\n<p style=\"text-align:right\">\u062a\u0639\u062f\u0627\u062f \u067e\u06cc\u06a9\u0633\u0644 \u0647\u0627\u06cc \u0627\u0641\u0642\u06cc \u0627\u06cc\u0646 \u062f\u0648\u0631\u0628\u06cc\u0646 2592 \u067e\u06cc\u06a9\u0633\u0644 \u0648 \u0639\u0645\u0648\u062f\u06cc 1944 \u067e\u06cc\u06a9\u0633\u0644 \u0645\u06cc\u0628\u0627\u0634\u062f \u06a9\u0647 \u062d\u0627\u0635\u0644 \u0636\u0631\u0628 \u0627\u06cc\u0646 \u062f\u0648 \u0639\u062f\u062f \u062f\u0631 \u0647\u0645 \u06a9\u06cc\u0641\u06cc\u062a 5 \u0645\u06af\u0627\u067e\u06cc\u06a9\u0633\u0644 \u0631\u0627 \u062a\u0634\u06a9\u06cc\u0644 \u0645\u06cc\u062f\u0647\u062f .</p>\r\n\r\n<p style=\"text-align:right\">\u0648\u0644\u062a\u0627\u0698 \u0648\u0631\u0648\u062f\u06cc \u0627\u06cc\u0646 \u062f\u0648\u0631\u0628\u06cc\u0646 \u0628\u06cc\u0646 10 \u062a\u0627 14 \u0648\u0644\u062a \u0627\u0633\u062a.</p>\r\n\r\n<p style=\"text-align:right\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u062c\u0631\u06cc\u0627\u0646 \u0645\u0635\u0631\u0641\u06cc \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 1 \u06cc\u0627 2 \u0627\u0645\u067e\u0631 \u0627\u0632 \u0646\u0648\u0639 \u062c\u0631\u06cc\u0627\u0646 \u062b\u0627\u0628\u062a DC \u0648 \u0645\u0635\u0631\u0641 \u0628\u0631\u0642\u06cc \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 \u0645\u0627\u06a9\u0633\u06cc\u0645\u0645 4 \u0648\u0627\u062a \u0631\u0627 \u0646\u06cc\u0632 \u062f\u0627\u0631\u062f \u0648 \u0647\u0645\u0686\u0646\u06cc\u0646 \u0627\u0632 \u0642\u0627\u0628\u0644\u06cc\u062a POE \u0646\u06cc\u0632 \u0628\u0631\u062e\u0648\u0631\u062f\u0627\u0631 \u0645\u06cc\u0628\u0627\u0634\u062f .</p>\r\n\r\n<p style=\"text-align:right\">\u0646\u062d\u0648\u0647 \u0627\u062a\u0635\u0627\u0644 \u062f\u0648\u0631\u0628\u06cc\u0646 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0628\u0647 \u062f\u0633\u062a\u06af\u0627\u0647 NVR \u0627\u0632 \u0637\u0631\u06cc\u0642 \u06a9\u0627\u0628\u0644 \u0634\u0628\u06a9\u0647 \u06cc\u0627 CAT6 \u0628\u0647 \u0645\u062a\u0631\u0627\u0698 \u062d\u062f\u0627\u06a9\u062b\u0631 200 \u0645\u062a\u0631 \u0648 \u0627\u0632 \u0637\u0631\u06cc\u0642 \u0633\u0648\u06a9\u062a \u0634\u0628\u06a9\u0647 RG 45 \u0645\u06cc\u0628\u0627\u0634\u062f .</p>\r\n\r\n<p style=\"text-align:right\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631 \u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0645\u062c\u0647\u0632 \u0628\u0647 \u0642\u0627\u0628\u0644\u06cc\u062a BLC (\u06cc\u06a9\u0633\u0627\u0646 \u06a9\u0631\u062f\u0646 \u062a\u0636\u0627\u062f \u0646\u0648\u0631\u06cc \u062f\u0631 \u0645\u062d\u06cc\u0637 \u0647\u0627\u06cc \u0631\u0648\u0634\u0646 \u0648 \u062a\u0627\u0631\u06cc\u06a9 ) \u0648 \u0642\u0627\u0628\u0644\u06cc\u062a WDR (\u062c\u0645\u0639 \u06a9\u0631\u062f\u0646 \u0646\u0648\u0631 \u0632\u06cc\u0627\u062f \u0628\u0647 \u0635\u0648\u0631\u062a \u0633\u062e\u062a \u0627\u0641\u0632\u0627\u0631\u06cc) \u0648 DAY/NIGHT ( \u062a\u0646\u0638\u06cc\u0645 \u0646\u0648\u0631 \u062f\u0631 \u0634\u0628 \u0648 \u0631\u0648\u0632 ) \u0645\u06cc\u0628\u0627\u0634\u062f .</p>\r\n\r\n<p style=\"text-align:right\">\u0641\u0627\u0635\u0644\u0647 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0644\u0646\u0632 \u062f\u0648\u0631\u0628\u06cc\u0646 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0627\u0632 \u0646\u0648\u0639 \u0644\u0646\u0632 \u062b\u0627\u0628\u062a 2.7 \u062a\u0627 13.5 \u0645\u06cc\u0644\u06cc \u0645\u062a\u0631\u06cc \u0645\u06cc \u0628\u0627\u0634\u062f.</p>\r\n\r\n<p style=\"text-align:right\"><a href=\"https://www.hik-look.com/cctv/\" target=\"_self\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631\u0628\u0633\u062a\u0647</a>&nbsp;\u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0628\u0631\u062f \u062f\u06cc\u062f \u062f\u0631 \u0634\u0628\u06cc \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 60 \u0645\u062a\u0631 \u0645\u0631\u0628\u0639 \u0631\u0627 \u067e\u0648\u0634\u0634 \u0645\u06cc\u062f\u0647\u062f .</p>\r\n\r\n<p style=\"text-align:right\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0647\u0645\u0686\u0646\u06cc\u0646 \u0627\u0632 \u0642\u0627\u0628\u0644\u06cc\u062a DNR ( \u06a9\u0627\u0647\u0634 \u0646\u0648\u06cc\u0632 \u062f\u0631 \u0634\u0628 ) \u0646\u06cc\u0632 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u06cc \u06a9\u0631\u062f\u0647 \u0648 \u062f\u0627\u0631\u0627\u06cc \u06a9\u0627\u0631\u062a \u062d\u0627\u0641\u0638\u0647 \u062f\u0627\u062e\u0644\u06cc 256 \u06af\u06cc\u06af\u0627\u0628\u0627\u06cc\u062a \u0645\u06cc \u0628\u0627\u0634\u062f.</p>\r\n\r\n<h3 style=\"text-align:right\">\u0645\u0634\u062e\u0635\u0627\u062a \u0641\u06cc\u0632\u06cc\u06a9\u06cc \u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631 \u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS</h3>\r\n\r\n<p style=\"text-align:right\">\u0628\u062f\u0646\u0647 \u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631\u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u062a\u0634\u06a9\u06cc\u0644 \u0634\u062f\u0647 \u0627\u0632 \u0641\u0644\u0632 \u0627\u0633\u062a \u0648 \u0645\u0642\u0627\u0648\u0645 \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u0628\u0627\u0631\u0646\u062f\u06af\u06cc \u0648 \u06af\u0631\u062f \u0648 \u062e\u0627\u06a9 \u06cc\u0627 \u0628\u0647 \u0627\u0635\u0637\u0644\u0627\u062d \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f (IP67).</p>\r\n\r\n<p style=\"text-align:right\">\u0645\u0646\u0627\u0633\u0628 \u0628\u0631\u0627\u06cc \u0646\u0635\u0628 \u062f\u0631 \u0645\u062d\u06cc\u0637 \u0647\u0627\u06cc \u062f\u0627\u062e\u0644\u06cc \u0648 \u0628\u06cc\u0631\u0648\u0646\u06cc .</p>", "<h2 style=\"text-align:right\"><span style=\"font-family:Moalla\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631\u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f DH-IPC-HFW3541TP-ZS</span></h2>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631 \u0628\u0633\u062a\u0647&nbsp;<u><a href=\"https://www.hik-look.com/dahua/\" target=\"_self\" title=\"\u062f\u0627\u0647\u0648\u0627\">\u062f\u0627\u0647\u0648\u0627</a></u>&nbsp;\u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0627\u0632 \u067e\u0631\u0641\u0631\u0648\u0634 \u062a\u0631\u06cc\u0646 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0633\u0631\u06cc \u062a\u062d\u062a \u0634\u0628\u06a9\u0647 \u06a9\u0645\u067e\u0627\u0646\u06cc \u062f\u0627\u0647\u0648\u0627 \u0645\u06cc\u0628\u0627\u0634\u062f \u06a9\u0647 \u0627\u0632 \u06a9\u06cc\u0641\u06cc\u062a \u0648 \u0642\u06cc\u0645\u062a \u0645\u0646\u0627\u0633\u0628\u06cc \u0628\u0631\u062e\u0648\u0631\u062f\u0627\u0631 \u0627\u0633\u062a.</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u062a\u0639\u062f\u0627\u062f \u067e\u06cc\u06a9\u0633\u0644 \u0647\u0627\u06cc \u0627\u0641\u0642\u06cc \u0627\u06cc\u0646 \u062f\u0648\u0631\u0628\u06cc\u0646 2592 \u067e\u06cc\u06a9\u0633\u0644 \u0648 \u0639\u0645\u0648\u062f\u06cc 1944 \u067e\u06cc\u06a9\u0633\u0644 \u0645\u06cc\u0628\u0627\u0634\u062f \u06a9\u0647 \u062d\u0627\u0635\u0644 \u0636\u0631\u0628 \u0627\u06cc\u0646 \u062f\u0648 \u0639\u062f\u062f \u062f\u0631 \u0647\u0645 \u06a9\u06cc\u0641\u06cc\u062a 5 \u0645\u06af\u0627\u067e\u06cc\u06a9\u0633\u0644 \u0631\u0627 \u062a\u0634\u06a9\u06cc\u0644 \u0645\u06cc\u062f\u0647\u062f .</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u0648\u0644\u062a\u0627\u0698 \u0648\u0631\u0648\u062f\u06cc \u0627\u06cc\u0646 \u062f\u0648\u0631\u0628\u06cc\u0646 \u0628\u06cc\u0646 10 \u062a\u0627 14 \u0648\u0644\u062a \u0627\u0633\u062a.</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u062c\u0631\u06cc\u0627\u0646 \u0645\u0635\u0631\u0641\u06cc \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 1 \u06cc\u0627 2 \u0627\u0645\u067e\u0631 \u0627\u0632 \u0646\u0648\u0639 \u062c\u0631\u06cc\u0627\u0646 \u062b\u0627\u0628\u062a DC \u0648 \u0645\u0635\u0631\u0641 \u0628\u0631\u0642\u06cc \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 \u0645\u0627\u06a9\u0633\u06cc\u0645\u0645 4 \u0648\u0627\u062a \u0631\u0627 \u0646\u06cc\u0632 \u062f\u0627\u0631\u062f \u0648 \u0647\u0645\u0686\u0646\u06cc\u0646 \u0627\u0632 \u0642\u0627\u0628\u0644\u06cc\u062a POE \u0646\u06cc\u0632 \u0628\u0631\u062e\u0648\u0631\u062f\u0627\u0631 \u0645\u06cc\u0628\u0627\u0634\u062f .</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u0646\u062d\u0648\u0647 \u0627\u062a\u0635\u0627\u0644 \u062f\u0648\u0631\u0628\u06cc\u0646 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0628\u0647 \u062f\u0633\u062a\u06af\u0627\u0647 NVR \u0627\u0632 \u0637\u0631\u06cc\u0642 \u06a9\u0627\u0628\u0644 \u0634\u0628\u06a9\u0647 \u06cc\u0627 CAT6 \u0628\u0647 \u0645\u062a\u0631\u0627\u0698 \u062d\u062f\u0627\u06a9\u062b\u0631 200 \u0645\u062a\u0631 \u0648 \u0627\u0632 \u0637\u0631\u06cc\u0642 \u0633\u0648\u06a9\u062a \u0634\u0628\u06a9\u0647 RG 45 \u0645\u06cc\u0628\u0627\u0634\u062f .</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u062f\u0648\u0631\u0628\u06cc\u0646 \u0645\u062f\u0627\u0631 \u0628\u0633\u062a\u0647 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0645\u062c\u0647\u0632 \u0628\u0647 \u0642\u0627\u0628\u0644\u06cc\u062a BLC (\u06cc\u06a9\u0633\u0627\u0646 \u06a9\u0631\u062f\u0646 \u062a\u0636\u0627\u062f \u0646\u0648\u0631\u06cc \u062f\u0631 \u0645\u062d\u06cc\u0637 \u0647\u0627\u06cc \u0631\u0648\u0634\u0646 \u0648 \u062a\u0627\u0631\u06cc\u06a9 ) \u0648 \u0642\u0627\u0628\u0644\u06cc\u062a WDR (\u062c\u0645\u0639 \u06a9\u0631\u062f\u0646 \u0646\u0648\u0631 \u0632\u06cc\u0627\u062f \u0628\u0647 \u0635\u0648\u0631\u062a \u0633\u062e\u062a \u0627\u0641\u0632\u0627\u0631\u06cc) \u0648 DAY/NIGHT ( \u062a\u0646\u0638\u06cc\u0645 \u0646\u0648\u0631 \u062f\u0631 \u0634\u0628 \u0648 \u0631\u0648\u0632 ) \u0645\u06cc\u0628\u0627\u0634\u062f .</span></p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-family:Moalla\">\u0641\u0627\u0635\u0644\u0647 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0644\u0646\u0632 \u062f\u0648\u0631\u0628\u06cc\u0646 \u062f\u0627\u0647\u0648\u0627 \u0645\u062f\u0644 DH-IPC-HFW3541TP-ZS \u0627\u0632 \u0646\u064